# WARNING: Under review - generated by LLM.

import pytest

from .tiny_llm_base import (
    CompactionError,
    EffectReceipt,
    ReceiptStore,
    SessionStore,
    compact_tool_results,
    expand_receipt_range,
    reexpand_receipt_message,
)


def _session_with_big_result(tmp_path, *, words=500):
    store = SessionStore(tmp_path, "test-model")
    session = store.create()
    session.append("user_message", content="inspect the log")
    call = session.append("tool_call", tool="read_file", arguments={"path": "log"})
    body = "line " * words
    session.append(
        "tool_result",
        tool_call_id=call.id,
        tool="read_file",
        is_error=False,
        content=body,
    )
    receipt = EffectReceipt(
        tool_call_id=call.id,
        tool="read_file",
        arguments={"path": "log"},
        exit_state="ok",
        result=body,
        changed_artifacts=(),
    )
    return session, call, receipt


def test_task_1_compact_replaces_oversized_tool_results(tmp_path):
    session, call, receipt = _session_with_big_result(tmp_path)
    store = ReceiptStore(tmp_path / "receipts.jsonl")
    store.put(receipt)

    result = compact_tool_results(session, store, max_result_bytes=100)

    assert result.compacted == 1
    assert result.saved_bytes > 0
    assert "compacted" in result.messages[0]["content"]


def test_task_1_compact_never_mutates_the_durable_trace(tmp_path):
    session, call, receipt = _session_with_big_result(tmp_path)
    store = ReceiptStore(tmp_path / "receipts.jsonl")
    store.put(receipt)
    before = [event.to_dict() for event in session.events]

    compact_tool_results(session, store, max_result_bytes=100)

    assert [event.to_dict() for event in session.events] == before


def test_task_1_compact_leaves_results_without_receipts_untouched(tmp_path):
    session, call, receipt = _session_with_big_result(tmp_path)
    store = ReceiptStore(tmp_path / "receipts.jsonl")

    result = compact_tool_results(session, store, max_result_bytes=100)

    assert result.compacted == 0
    assert "compacted" not in result.messages[0]["content"]


def test_task_2_compact_then_expand_recovers_the_omitted_middle(tmp_path):
    store = SessionStore(tmp_path, "test-model")
    session = store.create()
    session.append("user_message", content="inspect the log")
    call = session.append("tool_call", tool="read_file", arguments={"path": "log"})
    body = "\n".join(f"fact {number}" for number in range(1, 401)) + "\n"
    session.append(
        "tool_result",
        tool_call_id=call.id,
        tool="read_file",
        is_error=False,
        content=body,
    )
    receipt_store = ReceiptStore(tmp_path / "receipts.jsonl")
    receipt = EffectReceipt(
        tool_call_id=call.id,
        tool="read_file",
        arguments={"path": "log"},
        exit_state="ok",
        result=body,
        changed_artifacts=(),
    )
    receipt_store.put(receipt)

    result = compact_tool_results(session, receipt_store, max_result_bytes=100)
    rendering = result.messages[0]["content"]
    assert result.compacted == 1

    assert (
        reexpand_receipt_message(receipt_store, rendering, start=0, end=9) == body[:9]
    )
    assert reexpand_receipt_message(receipt_store, rendering) == body
    assert (
        expand_receipt_range(receipt_store, receipt.receipt_id, start=len(body) - 10)
        == body[-10:]
    )


def test_task_2_reexpansion_rejects_an_invalid_handle(tmp_path):
    store = ReceiptStore(tmp_path / "receipts.jsonl")

    with pytest.raises(CompactionError, match="does not reference"):
        reexpand_receipt_message(store, "no handle here")
    with pytest.raises(CompactionError, match="invalid receipt ID"):
        reexpand_receipt_message(store, "expand via receipt not-a-hash")
